styles:
:root{
  --obsidian:#050508;--void:#09090f;--navy:#080d1a;
  --cobalt:#1a3a6b;--azure:#2156a8;--ice:#4d9fe0;--pale:#a8d4f5;
  --gold-dk:#5a3e00;--gold-md:#b8860b;--gold:#d4a017;--gold-br:#f0c040;--gold-sh:#ffd966;
  --scar-dk:#4a0808;--scar:#8b1a1a;--crim:#c0392b;--flame:#e84040;
  --white:#f5f0e8;--offwhite:#ddd5c0;
  --gg:0 0 20px rgba(212,160,23,.45),0 0 55px rgba(212,160,23,.18);
  --gb:0 0 20px rgba(77,159,224,.45),0 0 55px rgba(77,159,224,.18);
  --bg:1px solid rgba(212,160,23,.32);
  --bb:1px solid rgba(77,159,224,.28);
}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth;font-size:16px}
body{background:var(--obsidian);color:var(--offwhite);font-family:'EB Garamond',Georgia,serif;font-size:1.05rem;line-height:1.75;overflow-x:hidden}
body.preloading{overflow:hidden}
body::before{content:'';position:fixed;inset:0;z-index:0;
  background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.04'/%3E%3C/svg%3E");
  opacity:.4;pointer-events:none}
::-webkit-scrollbar{width:5px}
::-webkit-scrollbar-track{background:var(--void)}
::-webkit-scrollbar-thumb{background:var(--gold-md);border-radius:3px}
::selection{background:rgba(212,160,23,.28);color:var(--gold-sh)}

/* ══ PRELOADER ══ */
#preloader{
  position:fixed;inset:0;z-index:9999;background:#000;
  display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1.5rem;
  transition:opacity .9s ease,visibility .9s ease;
}
#preloader.fade{opacity:0;visibility:hidden}
.pre-logo{
  width:min(820px,92vw);animation:logoIn 1s ease .2s both;
}
.pre-logo img{width:100%;height:auto;display:block}
@keyframes logoIn{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:scale(1)}}
.pre-status{font-family:'Share Tech Mono',monospace;font-size:.78rem;color:rgba(77,159,224,.7);letter-spacing:.28em;text-transform:uppercase;animation:fadeIn .5s ease 1.1s both}
.pre-bar-wrap{width:min(280px,60vw);height:2px;background:rgba(77,159,224,.12);position:relative;overflow:hidden;animation:fadeIn .5s ease 1s both}
.pre-bar-fill{height:100%;width:0;background:linear-gradient(90deg,var(--scar),var(--ice));box-shadow:0 0 8px rgba(77,159,224,.6);animation:barFill 1.5s ease 1s both}
.pre-pct{font-family:'Share Tech Mono',monospace;font-size:.7rem;color:rgba(77,159,224,.45);letter-spacing:.15em;animation:fadeIn .4s ease 1.1s both}
@keyframes barFill{to{width:92%}}
@keyframes fadeIn{to{opacity:1}}

/* ══ NAV ══ */
nav{position:fixed;top:0;left:0;right:0;z-index:100;background:rgba(5,5,8,.93);backdrop-filter:blur(18px);border-bottom:1px solid rgba(212,160,23,.18);height:54px;padding:0 1.5rem;display:flex;align-items:center;justify-content:space-between;opacity:0;animation:fadeIn .5s ease 2.8s both}
.nav-brand{font-family:'Cinzel',serif;font-size:.9rem;letter-spacing:.3em;color:var(--gold);font-weight:700;text-decoration:none}
.nav-links{display:flex;gap:1.4rem;list-style:none;align-items:center}
.nav-links a{font-family:'Share Tech Mono',monospace;font-size:.62rem;letter-spacing:.18em;color:var(--pale);text-decoration:none;text-transform:uppercase;transition:color .2s;position:relative;padding-bottom:2px}
.nav-links a::after{content:'';position:absolute;bottom:0;left:0;right:0;height:1px;background:var(--gold);transform:scaleX(0);transition:transform .2s}
.nav-links a:hover{color:var(--gold-br)}
.nav-links a:hover::after{transform:scaleX(1)}
.lang-toggle{font-family:'Share Tech Mono',monospace;font-size:.62rem;letter-spacing:.15em;padding:4px 11px;border:1px solid rgba(77,159,224,.4);color:var(--ice);background:transparent;cursor:pointer;text-transform:uppercase;transition:all .2s}
.lang-toggle:hover{background:rgba(77,159,224,.1);box-shadow:var(--gb)}
.lang-toggle.active{background:rgba(77,159,224,.15);border-color:var(--purple-bright);box-shadow:0 0 14px var(--purple-glow)}
.hamburger{display:none;flex-direction:column;gap:5px;background:none;border:none;cursor:pointer;padding:6px}
.hamburger span{width:22px;height:1.5px;background:var(--gold);display:block;transition:all .3s}
.mob-menu{display:none;position:fixed;top:54px;left:0;right:0;z-index:99;background:rgba(5,5,8,.97);border-bottom:1px solid rgba(212,160,23,.18);padding:1.5rem;flex-direction:column;gap:.8rem}
.mob-menu.open{display:flex}
.mob-menu a{font-family:'Share Tech Mono',monospace;font-size:.78rem;letter-spacing:.12em;color:var(--pale);text-decoration:none;text-transform:uppercase;padding:.5rem 0;border-bottom:1px solid rgba(212,160,23,.08)}

/* ══ HERO ══ */
#hero{min-height:100vh;position:relative;overflow:hidden;display:flex;align-items:center;padding:80px 1.5rem 4rem;
  background:radial-gradient(ellipse 65% 55% at 55% 40%,rgba(21,56,107,.5) 0%,transparent 65%),
    radial-gradient(ellipse 40% 40% at 10% 25%,rgba(139,26,26,.18) 0%,transparent 55%),
    radial-gradient(ellipse 30% 35% at 90% 70%,rgba(33,86,168,.22) 0%,transparent 55%),
    var(--obsidian)}
#hero::before{content:'';position:absolute;left:-10%;right:-10%;height:1.5px;background:linear-gradient(90deg,transparent,var(--scar) 20%,var(--flame) 50%,var(--scar) 80%,transparent);top:35%;animation:scanBeam 6s ease-in-out infinite;opacity:.35}
@keyframes scanBeam{0%,100%{top:18%;opacity:.2}50%{top:82%;opacity:.45}}
#hero::after{content:'';position:absolute;inset:0;background:repeating-linear-gradient(0deg,transparent,transparent 3px,rgba(0,0,0,.05) 3px,rgba(0,0,0,.05) 4px);pointer-events:none;z-index:1}
.hero-inner{position:relative;z-index:2;max-width:1060px;width:100%;margin:0 auto;display:grid;grid-template-columns:280px 1fr;gap:5rem;align-items:center}
.photo-outer{position:relative;display:flex;justify-content:center;align-items:center}
.photo-ring{position:absolute;width:280px;height:280px;border-radius:50%;border:1px solid rgba(212,160,23,.25);animation:spin 25s linear infinite}
.photo-ring::before,.photo-ring::after{content:'◆';position:absolute;color:var(--gold);font-size:.6rem;left:50%;transform:translateX(-50%)}
.photo-ring::before{top:-8px}.photo-ring::after{bottom:-8px}
.photo-ring2{position:absolute;width:300px;height:300px;border-radius:50%;border:1px solid rgba(77,159,224,.12);animation:spin 40s linear infinite reverse}
.photo-circle{width:230px;height:230px;border-radius:50%;overflow:hidden;border:2px solid var(--gold-md);box-shadow:0 0 0 6px rgba(212,160,23,.08),0 0 40px rgba(212,160,23,.3),0 0 80px rgba(212,160,23,.12);position:relative;z-index:2;animation:pulsePhoto 4s ease-in-out infinite}
.photo-circle img{width:100%;height:100%;object-fit:cover;object-position:top center;filter:contrast(1.1) brightness(.88) sepia(.12)}
@keyframes spin{to{transform:rotate(360deg)}}
@keyframes pulsePhoto{0%,100%{box-shadow:0 0 0 6px rgba(212,160,23,.08),0 0 40px rgba(212,160,23,.3),0 0 80px rgba(212,160,23,.12)}50%{box-shadow:0 0 0 8px rgba(212,160,23,.15),0 0 60px rgba(212,160,23,.5),0 0 100px rgba(212,160,23,.2)}}
.photo-status{position:absolute;bottom:16px;right:14px;z-index:3;font-family:'Share Tech Mono',monospace;font-size:.58rem;letter-spacing:.15em;color:var(--ice);background:rgba(5,5,8,.9);padding:3px 9px;border:1px solid rgba(77,159,224,.3)}
.status-dot{width:6px;height:6px;border-radius:50%;background:#00ff88;display:inline-block;margin-right:4px;animation:blink 1.5s infinite}
@keyframes blink{0%,100%{opacity:1}50%{opacity:.3}}
.hero-eyebrow{font-family:'Share Tech Mono',monospace;font-size:.66rem;letter-spacing:.3em;color:var(--ice);text-transform:uppercase;margin-bottom:.75rem;opacity:0;animation:slideUp .7s ease 2.6s both}
.hero-name{font-family:'Cinzel Decorative',serif;font-size:clamp(1.8rem,4.5vw,3.2rem);font-weight:900;line-height:1.1;color:var(--white);margin-bottom:.6rem;opacity:0;animation:slideUp .7s ease 2.7s both}
.hero-name span{background:linear-gradient(90deg,var(--gold-md),var(--gold-br),var(--gold-md));-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;background-size:200%;animation:shimmer 3s linear infinite}
@keyframes shimmer{to{background-position:200% center}}
.hero-ticker{font-family:'Share Tech Mono',monospace;font-size:.7rem;letter-spacing:.1em;color:var(--ice);margin-bottom:1.75rem;line-height:2;opacity:0;animation:slideUp .7s ease 2.8s both}
.ticker-item{display:inline-block;margin-right:1.5rem;padding:2px 10px;background:rgba(77,159,224,.08);border:1px solid rgba(77,159,224,.2)}
.hero-bio{font-size:1rem;line-height:1.8;color:rgba(221,213,192,.82);max-width:500px;margin-bottom:2rem;opacity:0;animation:slideUp .7s ease 2.9s both}
.hero-ctas{display:flex;flex-wrap:wrap;gap:1rem;margin-bottom:2.5rem;opacity:0;animation:slideUp .7s ease 3s both}
.btn-gold{font-family:'Cinzel',serif;font-size:.75rem;letter-spacing:.18em;text-transform:uppercase;text-decoration:none;padding:.75rem 2rem;background:linear-gradient(135deg,var(--gold-dk),var(--gold));color:var(--obsidian);font-weight:700;clip-path:polygon(8px 0%,100% 0%,calc(100% - 8px) 100%,0% 100%);transition:all .25s;display:inline-block}
.btn-gold:hover{background:linear-gradient(135deg,var(--gold),var(--gold-sh));box-shadow:var(--gg);transform:translateY(-2px)}
.btn-outline{font-family:'Share Tech Mono',monospace;font-size:.7rem;letter-spacing:.15em;text-transform:uppercase;text-decoration:none;padding:.75rem 1.8rem;background:transparent;color:var(--ice);border:1px solid rgba(77,159,224,.45);clip-path:polygon(8px 0%,100% 0%,calc(100% - 8px) 100%,0% 100%);transition:all .25s;display:inline-block}
.btn-outline:hover{background:rgba(77,159,224,.08);border-color:var(--ice);box-shadow:var(--gb);transform:translateY(-2px)}
.hero-stats{display:flex;gap:1.5rem;flex-wrap:wrap;opacity:0;animation:slideUp .7s ease 3.1s both}
.hstat{text-align:center}.hstat-n{font-family:'Cinzel Decorative',serif;font-size:1.8rem;color:var(--gold);line-height:1}
.hstat-l{font-family:'Share Tech Mono',monospace;font-size:.56rem;letter-spacing:.18em;color:var(--pale);text-transform:uppercase;margin-top:.2rem}
.hstat-div{width:1px;background:rgba(212,160,23,.25);align-self:stretch}
@keyframes slideUp{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:translateY(0)}}

/* ══ SECTIONS ══ */
.section-wrap{position:relative;z-index:2;padding:6rem 1.5rem;max-width:1100px;margin:0 auto}
.sec-head{display:flex;align-items:center;gap:1.5rem;margin-bottom:3.5rem}
.sec-num{font-family:'Share Tech Mono',monospace;font-size:.62rem;color:var(--crim, #c0392b);letter-spacing:.2em;writing-mode:vertical-rl;transform:rotate(180deg)}
.sec-titles{flex:1}
.sec-tag{font-family:'Share Tech Mono',monospace;font-size:.62rem;color:var(--ice);letter-spacing:.3em;text-transform:uppercase;display:block;margin-bottom:.25rem}
.sec-title{font-family:'Cinzel',serif;font-size:clamp(1.5rem,3vw,2.3rem);font-weight:600;color:var(--white);position:relative;display:inline-block}
.sec-title::after{content:'';position:absolute;bottom:-5px;left:0;height:2px;width:55%;background:linear-gradient(90deg,var(--gold),transparent)}
.sec-line{flex:0 0 auto;width:70px;height:1px;background:linear-gradient(90deg,rgba(212,160,23,.4),transparent)}
.arc-div{text-align:center;padding:.5rem 0;position:relative;z-index:2;color:rgba(212,160,23,.25);font-size:1.1rem;letter-spacing:1.5rem}
.reveal{opacity:0;transform:translateY(28px);transition:opacity .7s ease,transform .7s ease}
.reveal.vis{opacity:1;transform:translateY(0)}

/* ══ ARCHITECT ══ */
#architect{background:radial-gradient(ellipse 60% 50% at 0% 50%,rgba(77,159,224,.06) 0%,transparent 60%),radial-gradient(ellipse 40% 60% at 100% 30%,rgba(192,57,43,.07) 0%,transparent 55%),var(--void);position:relative;z-index:2}
.architect-grid{display:grid;grid-template-columns:1fr 1.3fr;gap:4rem;align-items:start}
.intj-badge{display:inline-flex;align-items:center;gap:.75rem;background:rgba(8,13,26,.9);border:1px solid rgba(77,159,224,.3);padding:.5rem 1.2rem;margin-bottom:2rem}
.intj-code{font-family:'Share Tech Mono',monospace;font-size:1.1rem;color:var(--ice);letter-spacing:.25em;font-weight:700}
.intj-label{font-family:'Share Tech Mono',monospace;font-size:.6rem;color:rgba(168,212,245,.6);letter-spacing:.15em;text-transform:uppercase}
.architect-quote{position:relative;background:rgba(8,13,26,.85);border:1px solid rgba(77,159,224,.2);border-left:3px solid var(--ice);padding:2rem 2rem 2rem 2.5rem;margin-bottom:2rem}
.architect-quote::before{content:'"';font-family:'Cinzel Decorative',serif;font-size:4rem;color:rgba(77,159,224,.12);position:absolute;top:-.5rem;left:1rem;line-height:1}
.architect-quote p{font-size:1rem;color:rgba(221,213,192,.85);font-style:italic;line-height:1.85}
.trait-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem}
.trait-card{background:rgba(8,13,26,.9);border:var(--bg);padding:1.25rem 1rem;transition:all .3s;position:relative;overflow:hidden}
.trait-card::before{content:'';position:absolute;top:0;left:0;width:2px;height:100%;background:linear-gradient(180deg,var(--ice),var(--scar))}
.trait-card:hover{border-color:rgba(212,160,23,.55);box-shadow:var(--gg);transform:translateY(-2px)}
.trait-icon{font-size:1.3rem;margin-bottom:.4rem;display:block}
.trait-name{font-family:'Cinzel',serif;font-size:.78rem;font-weight:600;color:var(--gold-br);letter-spacing:.08em;margin-bottom:.25rem}
.trait-desc{font-size:.82rem;color:rgba(221,213,192,.65);line-height:1.5}
.mbti-bars{margin-top:2rem}
.mbti-row{display:flex;align-items:center;gap:1rem;margin-bottom:1rem;font-family:'Share Tech Mono',monospace;font-size:.68rem}
.mbti-l{color:var(--pale);width:20px;text-align:right}
.mbti-r{color:rgba(168,212,245,.5);width:20px}
.mbti-track{flex:1;height:4px;background:rgba(255,255,255,.06);position:relative}
.mbti-fill{height:100%;position:absolute;top:0;background:linear-gradient(90deg,var(--scar),var(--ice));box-shadow:0 0 6px rgba(77,159,224,.4)}

/* ══ FORGE ══ */
#forge{background:var(--navy);position:relative;z-index:2}
.forge-tabs{display:flex;gap:0;margin-bottom:2.5rem;border-bottom:1px solid rgba(212,160,23,.2);overflow-x:auto}
.forge-tab{font-family:'Share Tech Mono',monospace;font-size:.65rem;letter-spacing:.15em;text-transform:uppercase;padding:.75rem 1.4rem;background:transparent;color:rgba(168,212,245,.5);border:none;cursor:pointer;border-bottom:2px solid transparent;margin-bottom:-1px;transition:all .2s;white-space:nowrap}
.forge-tab.active{color:var(--ice);border-bottom-color:#c0392b;background:rgba(77,159,224,.05)}
.forge-tab:hover{color:var(--pale);background:rgba(77,159,224,.04)}
.forge-panel{display:none}
.forge-panel.active{display:block}
.svc-note{font-family:'Share Tech Mono',monospace;font-size:.66rem;color:rgba(168,212,245,.5);letter-spacing:.08em;background:rgba(8,13,26,.8);border-left:2px solid var(--scar);padding:.5rem 1rem;margin-bottom:2rem}
.timeline{position:relative;padding-left:2.5rem}
.timeline::before{content:'';position:absolute;left:0;top:0;bottom:0;width:1px;background:linear-gradient(180deg,var(--gold),var(--azure),var(--gold))}
.tl-item{position:relative;margin-bottom:2rem;padding:1.35rem 1.35rem;background:rgba(8,13,26,.75);border:1px solid rgba(212,160,23,.12);transition:border-color .3s}
.tl-item:hover{border-color:rgba(212,160,23,.32);box-shadow:0 0 18px rgba(212,160,23,.05)}
.tl-node{position:absolute;left:-2.5rem;top:1.5rem;transform:translateX(-50%);width:11px;height:11px;background:var(--gold);clip-path:polygon(50% 0%,100% 50%,50% 100%,0% 50%);box-shadow:var(--gg)}
.tl-date{font-family:'Share Tech Mono',monospace;font-size:.65rem;color:var(--gold-md);letter-spacing:.1em;margin-bottom:.35rem}
.tl-title{font-family:'Cinzel',serif;font-size:1rem;font-weight:600;color:var(--white);margin-bottom:.2rem}
.tl-company{font-family:'Share Tech Mono',monospace;font-size:.7rem;color:var(--ice);letter-spacing:.08em;margin-bottom:.7rem}
.tl-tags{display:flex;flex-wrap:wrap;gap:.3rem;margin-bottom:.7rem}
.tag{font-family:'Share Tech Mono',monospace;font-size:.57rem;letter-spacing:.1em;padding:2px 8px;text-transform:uppercase}
.tag-b{background:rgba(33,86,168,.2);border:1px solid rgba(77,159,224,.22);color:var(--pale)}
.tag-g{background:rgba(90,62,0,.25);border:1px solid rgba(212,160,23,.3);color:var(--gold-sh)}
.tag-r{background:rgba(139,26,26,.22);border:1px solid rgba(192,57,43,.28);color:#f5a0a0}
.tl-bullets{list-style:none;margin-top:.4rem}
.tl-bullets li{font-size:.87rem;color:rgba(221,213,192,.72);line-height:1.65;padding-left:1.2rem;position:relative;margin-bottom:.2rem}
.tl-bullets li::before{content:"▸";position:absolute;left:0;color:var(--ice)}

/* ══ SYSTEMS ══ */
.sys-intro{font-family:'Share Tech Mono',monospace;font-size:.7rem;color:rgba(168,212,245,.5);letter-spacing:.1em;margin-bottom:2rem}
.sys-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:2rem}
.sys-col{background:rgba(8,13,26,.8);border:var(--bb);padding:1.75rem 1.5rem}
.sys-col-title{font-family:'Cinzel',serif;font-size:.95rem;font-weight:600;color:var(--gold-br);margin-bottom:.25rem}
.sys-col-sub{font-family:'Share Tech Mono',monospace;font-size:.6rem;color:var(--ice);letter-spacing:.18em;text-transform:uppercase;margin-bottom:1.5rem;padding-bottom:.75rem;border-bottom:1px solid rgba(77,159,224,.15)}
.sys-skill{margin-bottom:1.1rem}
.sys-skill-head{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:.3rem}
.sys-skill-name{font-family:'Share Tech Mono',monospace;font-size:.67rem;color:var(--offwhite);letter-spacing:.06em}
.sys-skill-pct{font-family:'Share Tech Mono',monospace;font-size:.6rem;color:var(--gold-md)}
.sys-skill-lvl{font-family:'Share Tech Mono',monospace;font-size:.55rem;color:var(--ice);margin-left:.4rem}
.sys-bar{height:3px;background:rgba(255,255,255,.07)}
.sys-fill{height:100%;background:linear-gradient(90deg,var(--scar),var(--ice));box-shadow:0 0 5px rgba(77,159,224,.35)}
.sys-tags{display:flex;flex-wrap:wrap;gap:.35rem;margin-top:1.25rem}

/* ══ NEXUS ══ */
.nexus-grid{display:grid;grid-template-columns:1fr 1fr;gap:2rem}
.nexus-card{background:rgba(8,13,26,.85);border:var(--bb);padding:1.75rem}
.nexus-card-head{display:flex;align-items:center;gap:.75rem;margin-bottom:.3rem}
.nexus-icon{font-size:1.1rem}
.nexus-title{font-family:'Cinzel',serif;font-size:.95rem;font-weight:600;color:var(--white)}
.nexus-sub{font-family:'Share Tech Mono',monospace;font-size:.58rem;color:var(--ice);letter-spacing:.15em;text-transform:uppercase;margin-bottom:1rem;padding-bottom:.5rem;border-bottom:1px solid rgba(77,159,224,.12)}
.nexus-project{background:rgba(5,5,8,.6);border:1px solid rgba(77,159,224,.12);padding:1.2rem;margin-bottom:1rem}
.nexus-proj-title{font-family:'Cinzel',serif;font-size:.88rem;font-weight:600;color:var(--gold-br);margin-bottom:.5rem}
.nexus-proj-desc{font-size:.85rem;color:rgba(221,213,192,.7);line-height:1.6;margin-bottom:.75rem}
.nexus-quote{background:rgba(8,13,26,.9);border-left:2px solid var(--gold);padding:1.25rem 1.5rem;font-style:italic;font-size:.92rem;color:rgba(221,213,192,.8);line-height:1.8;margin-bottom:1rem}
.nexus-btns{display:flex;flex-wrap:wrap;gap:.5rem;margin-top:.75rem}
.nexus-btn{font-family:'Share Tech Mono',monospace;font-size:.58rem;letter-spacing:.1em;text-transform:uppercase;padding:5px 12px;border:1px solid rgba(77,159,224,.25);color:var(--pale);background:transparent;cursor:pointer;transition:all .2s}
.nexus-btn:hover{background:rgba(77,159,224,.08);border-color:var(--ice)}
.nexus-status{font-family:'Share Tech Mono',monospace;font-size:.6rem;color:#c0392b;letter-spacing:.1em}
.infra-bar{background:rgba(5,5,8,.85);border:1px solid rgba(77,159,224,.15);padding:.75rem 1.25rem;margin-bottom:1.5rem;display:flex;gap:2rem;flex-wrap:wrap}
.infra-item{display:flex;flex-direction:column;gap:.2rem}
.infra-label{font-family:'Share Tech Mono',monospace;font-size:.56rem;color:#8b1a1a;letter-spacing:.15em;text-transform:uppercase}
.infra-val{font-family:'Share Tech Mono',monospace;font-size:.68rem;color:var(--pale);letter-spacing:.08em}
.infra-dot{width:6px;height:6px;border-radius:50%;background:#8b1a1a;display:inline-block;margin-right:4px;animation:blink 1.5s infinite}

/* ══ ATHENEUM ══ */
#atheneum{background:radial-gradient(ellipse 70% 40% at 50% 0%,rgba(33,86,168,.07) 0%,transparent 55%),var(--obsidian);position:relative;z-index:2}
.wiki-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1.5rem}
.wiki-card{background:rgba(8,13,26,.85);border:1px solid rgba(212,160,23,.18);padding:1.75rem 1.5rem;position:relative;overflow:hidden;transition:all .3s;display:flex;flex-direction:column}
.wiki-card:hover{border-color:rgba(212,160,23,.45);box-shadow:var(--gg);transform:translateY(-3px)}
.wiki-cat{font-family:'Share Tech Mono',monospace;font-size:.58rem;letter-spacing:.2em;color:var(--ice);text-transform:uppercase;margin-bottom:.6rem;display:flex;align-items:center;gap:.5rem}
.wiki-cat-line{flex:1;height:1px;background:rgba(77,159,224,.2)}
.wiki-title{font-family:'Cinzel',serif;font-size:1rem;font-weight:600;color:var(--white);margin-bottom:.75rem;line-height:1.3}
.wiki-excerpt{font-size:.87rem;color:rgba(221,213,192,.68);line-height:1.7;flex:1}
.wiki-axiom{margin-top:1rem;padding-top:.75rem;border-top:1px solid rgba(212,160,23,.15);font-family:'Share Tech Mono',monospace;font-size:.6rem;color:var(--ice);letter-spacing:.08em;text-transform:uppercase;line-height:1.5}

/* ══ CONTACT ══ */
#contact{position:relative;z-index:2;background:radial-gradient(ellipse 60% 50% at 50% 100%,rgba(139,26,26,.12) 0%,transparent 55%),var(--void);padding:6rem 1.5rem}
.contact-inner{max-width:700px;margin:0 auto;text-align:center}
.contact-title{font-family:'Cinzel Decorative',serif;font-size:clamp(1.8rem,4vw,2.8rem);color:var(--white);margin-bottom:.6rem}
.contact-sub{font-size:.95rem;color:rgba(221,213,192,.55);font-style:italic;margin-bottom:2.5rem}
.contact-nexus{display:flex;justify-content:center;gap:2.5rem;flex-wrap:wrap;margin-bottom:2.5rem}
.cn-item{display:flex;flex-direction:column;align-items:center;gap:.4rem;text-decoration:none;transition:all .2s}
.cn-item:hover .cn-val{color:var(--gold-br);text-shadow:0 0 10px rgba(240,192,64,.4)}
.cn-label{font-family:'Share Tech Mono',monospace;font-size:.58rem;letter-spacing:.2em;color:var(--ice);text-transform:uppercase}
.cn-icon{font-size:1.4rem}
.cn-val{font-size:.9rem;color:var(--offwhite);transition:all .2s}
.transmit-form{background:rgba(8,13,26,.85);border:1px solid rgba(77,159,224,.2);padding:2.5rem;text-align:left;position:relative;overflow:hidden}
.transmit-form::before{content:'[ SECURE COMMUNICATION CHANNEL ]';position:absolute;top:0;left:0;right:0;text-align:center;font-family:'Share Tech Mono',monospace;font-size:.56rem;color:rgba(77,159,224,.3);letter-spacing:.18em;padding:.4rem;border-bottom:1px solid rgba(77,159,224,.1)}
.form-title{font-family:'Cinzel',serif;font-size:1.1rem;font-weight:600;color:var(--white);margin-bottom:.3rem;margin-top:1rem}
.form-sub{font-family:'Share Tech Mono',monospace;font-size:.6rem;color:var(--ice);letter-spacing:.15em;text-transform:uppercase;margin-bottom:1.5rem}
.form-group{margin-bottom:1.25rem}
.form-label{font-family:'Share Tech Mono',monospace;font-size:.6rem;letter-spacing:.18em;color:var(--pale);text-transform:uppercase;display:block;margin-bottom:.4rem}
.form-input,.form-textarea{width:100%;background:rgba(5,5,8,.7);border:1px solid rgba(77,159,224,.2);color:var(--offwhite);font-family:'Share Tech Mono',monospace;font-size:.8rem;padding:.65rem .9rem;outline:none;transition:border-color .2s,box-shadow .2s}
.form-input:focus,.form-textarea:focus{border-color:rgba(77,159,224,.5);box-shadow:0 0 0 1px rgba(77,159,224,.15)}
.form-input::placeholder,.form-textarea::placeholder{color:rgba(168,212,245,.25);font-style:italic}
.form-textarea{resize:vertical;min-height:110px}
.btn-transmit{width:100%;padding:.85rem;background:linear-gradient(135deg,rgba(77,159,224,.15),rgba(77,159,224,.08));border:1px solid rgba(77,159,224,.4);color:var(--ice);font-family:'Share Tech Mono',monospace;font-size:.72rem;letter-spacing:.2em;text-transform:uppercase;cursor:pointer;transition:all .25s;display:flex;align-items:center;justify-content:center;gap:.75rem}
.btn-transmit:hover{background:rgba(77,159,224,.18);border-color:var(--ice);box-shadow:var(--gb)}

footer{background:var(--obsidian);border-top:1px solid rgba(212,160,23,.12);text-align:center;padding:1.75rem 1.5rem;position:relative;z-index:2}
footer p{font-family:'Share Tech Mono',monospace;font-size:.58rem;color:rgba(168,212,245,.25);letter-spacing:.15em;text-transform:uppercase}
footer span{color:var(--gold-md)}
.rune-bg{position:fixed;inset:0;z-index:0;pointer-events:none;overflow:hidden}
.rune{position:absolute;color:rgba(212,160,23,.025);font-family:'Cinzel',serif;font-size:9rem;animation:floatRune linear infinite;user-select:none}
@keyframes floatRune{from{transform:translateY(110vh) rotate(0deg);opacity:0}10%{opacity:1}90%{opacity:1}to{transform:translateY(-20vh) rotate(360deg);opacity:0}}

@media(max-width:900px){
  .hero-inner{grid-template-columns:1fr;text-align:center;gap:2.5rem}
  .photo-outer{order:-1}
  .hero-bio,.hero-ctas,.hero-stats{justify-content:center}
  .hero-bio{margin-inline:auto}
  .architect-grid,.nexus-grid{grid-template-columns:1fr}
  .sys-grid,.wiki-grid{grid-template-columns:1fr}
  .trait-grid{grid-template-columns:1fr 1fr}
  .nav-links{display:none}
  .hamburger{display:flex}
  .section-wrap{padding:4rem 1rem}
  .photo-circle{width:180px;height:180px}
  .photo-ring{width:220px;height:220px}
  .photo-ring2{width:240px;height:240px}
  .timeline{padding-left:1.5rem}
  .tl-node{left:-1.5rem}
  .forge-tabs{overflow-x:auto}
}
@media(max-width:500px){
  .trait-grid{grid-template-columns:1fr}
  .hero-stats{gap:1rem}
  .hero-name{font-size:1.8rem}
}


