/* ═══ ARQUEOFUTURIST BUTTONS — FORGED STEEL + SCARLET FIRE ═══ */

/* Primary: "Contact Me" — Scarlet forge with gold edge */
.btn-gold {
  position: relative;
  background: linear-gradient(135deg, #6b0000 0%, #a01010 45%, #8b1a1a 100%) !important;
  color: #ffd966 !important;
  font-weight: 700 !important;
  font-size: .78rem !important;
  letter-spacing: .22em !important;
  border: 1px solid rgba(212,160,23,.6) !important;
  text-shadow: 0 0 8px rgba(255,217,102,.5) !important;
  box-shadow:
    0 0 0 1px rgba(192,57,43,.4),
    0 0 18px rgba(192,57,43,.35),
    inset 0 1px 0 rgba(255,200,100,.15) !important;
  clip-path: polygon(10px 0%, 100% 0%, calc(100% - 10px) 100%, 0% 100%) !important;
  transition: all .25s !important;
  overflow: visible !important;
}
.btn-gold::before {
  content: '';
  position: absolute; inset: 0;
  background: linear-gradient(180deg, rgba(255,150,50,.08) 0%, transparent 60%);
  pointer-events: none;
}
.btn-gold:hover {
  background: linear-gradient(135deg, #8b1010 0%, #c0392b 45%, #a01a1a 100%) !important;
  box-shadow:
    0 0 0 1px rgba(212,160,23,.7),
    0 0 28px rgba(232,64,64,.55),
    0 0 55px rgba(192,57,43,.25),
    inset 0 1px 0 rgba(255,200,100,.2) !important;
  transform: translateY(-3px) !important;
  color: #fff !important;
  text-shadow: 0 0 12px rgba(255,255,255,.6) !important;
}

/* Secondary: "View Experience" — Cyan terminal with blue neon */
.btn-outline {
  position: relative;
  background: rgba(0,20,40,.7) !important;
  color: #00e5ff !important;
  font-weight: 700 !important;
  font-size: .75rem !important;
  letter-spacing: .2em !important;
  border: 1px solid #00aacc !important;
  text-shadow: 0 0 8px rgba(0,229,255,.55) !important;
  box-shadow:
    0 0 0 1px rgba(0,180,220,.2),
    0 0 16px rgba(0,180,220,.25),
    inset 0 0 20px rgba(0,100,160,.12) !important;
  clip-path: polygon(10px 0%, 100% 0%, calc(100% - 10px) 100%, 0% 100%) !important;
  transition: all .25s !important;
}
.btn-outline::after {
  content: '';
  position: absolute; inset: 0;
  background: linear-gradient(180deg, rgba(0,200,255,.06) 0%, transparent 60%);
  pointer-events: none;
}
.btn-outline:hover {
  background: rgba(0,40,70,.85) !important;
  border-color: #00e5ff !important;
  box-shadow:
    0 0 0 1px rgba(0,229,255,.5),
    0 0 30px rgba(0,200,255,.45),
    0 0 60px rgba(0,150,200,.2),
    inset 0 0 25px rgba(0,120,180,.15) !important;
  transform: translateY(-3px) !important;
  color: #fff !important;
  text-shadow: 0 0 14px rgba(0,229,255,.8) !important;
}

/* Scanline glitch shimmer on both buttons */
@keyframes btn-shimmer {
  0%   { background-position: -200% center; }
  100% { background-position: 200% center; }
}


/* ═══ FORGE TABS — NEON TERMINAL STYLE ═══ */
