/* Professional hierarchy over legacy cyberpunk effects */
:root {
  --purple-deep: #580f8b;
  --purple-bright: #7b20b5;
  --purple-soft: #c98cff;
  --purple-glow: rgba(88,15,139,.42);
  --violet: #9b5de5;
  --olive: #718238;
  --olive-soft: #a7b86a;
}
.hero-bio { max-width: 620px; }
.intj-badge { border-color: rgba(212,160,23,.35) !important; }
.professional-evidence { margin-top: 1.5rem; padding: .85rem 1rem; border-left: 2px solid var(--gold); background: rgba(8,13,26,.72); font-family: 'Share Tech Mono', monospace; font-size: .68rem; line-height: 1.6; color: rgba(221,213,192,.68); }
.mbti-bars { display: none !important; }
.forge-tab.active { border-bottom-color: var(--purple-bright) !important; background: linear-gradient(180deg, rgba(88,15,139,.12), transparent) !important; }
.nav-links a:hover, .mob-menu a:hover { color: var(--purple-soft) !important; }
.lang-toggle:hover { border-color: var(--purple-bright) !important; color: var(--purple-soft) !important; box-shadow: 0 0 14px var(--purple-glow) !important; }
.sec-title::after { background: linear-gradient(90deg, var(--gold), var(--purple-bright), transparent) !important; }
.sec-line { background: linear-gradient(90deg, rgba(212,160,23,.45), rgba(123,32,181,.7), transparent) !important; }
.arc-div { color: rgba(155,93,229,.48) !important; }
.tl-node { background: linear-gradient(135deg, var(--gold), var(--purple-bright)) !important; box-shadow: 0 0 9px rgba(123,32,181,.5) !important; }
.timeline::before { background: linear-gradient(180deg, var(--gold), var(--purple-bright), var(--olive), var(--gold)) !important; }
.tag-g { border-color: rgba(113,130,56,.7) !important; color: var(--olive-soft) !important; background: rgba(113,130,56,.1) !important; }
.tag-r { border-color: rgba(155,93,229,.48) !important; }
.sys-col-title { text-shadow: 0 0 10px rgba(123,32,181,.45) !important; }
.sys-col-sub { color: var(--purple-soft) !important; }
.sys-fill::before { background-image: repeating-linear-gradient(90deg, var(--purple-bright) 0px, var(--purple-bright) 6px, transparent 6px, transparent 9px) !important; box-shadow: 0 0 6px rgba(123,32,181,.55) !important; }
.sys-skill-lvl { color: var(--purple-soft) !important; }
.infra-dot { background: var(--olive-soft) !important; box-shadow: 0 0 8px rgba(167,184,106,.6) !important; }
.nexus-sub, .wiki-cat { color: var(--violet) !important; }
.nexus-card:hover { border-color: rgba(123,32,181,.55) !important; box-shadow: 0 0 20px rgba(88,15,139,.16) !important; }
.nexus-btn:hover { color: var(--purple-soft) !important; border-color: rgba(123,32,181,.7) !important; }
.cn-item:hover { border-color: rgba(123,32,181,.65) !important; }
.cn-label { color: var(--purple-soft) !important; }
.status-dot { background: var(--olive-soft) !important; box-shadow: 0 0 6px rgba(167,184,106,.65); }
.tag-p { color: #c98cff !important; border-color: rgba(123,32,181,.65) !important; background: rgba(88,15,139,.2) !important; }
.omega-role { border-left: 2px solid var(--purple-bright) !important; box-shadow: inset 12px 0 24px rgba(88,15,139,.055); }
.omega-role .tl-node { background: var(--purple-bright) !important; box-shadow: 0 0 10px var(--purple-glow) !important; }
.omega-role .tl-date, .omega-role .tl-company { color: #c98cff !important; }
.omega-role:hover { border-color: rgba(123,32,181,.7) !important; box-shadow: 0 0 20px rgba(88,15,139,.16) !important; }
.wiki-card:nth-child(3n) { border-top-color: rgba(123,32,181,.62) !important; }
.wiki-card:nth-child(3n) .wiki-cat, .wiki-card:nth-child(3n) .wiki-axiom { color: #c98cff !important; }
.wiki-cat, .sec-tag, .hero-eyebrow { letter-spacing: .18em; }


:root {
  --obsidian:#030306;--void:#07070c;--navy:#07101f;
  --ice:#58b8df;--pale:#c5e7f3;
  --gold:#e1b52c;--gold-br:#ffd45a;--gold-sh:#ffe49a;
  --purple-deep:#31104f;--purple-bright:#7b2cbf;--purple-soft:#d2a4f4;
  --purple-glow:rgba(123,44,191,.36);--violet:#a56de2;
  --olive:#738238;--olive-soft:#b2c36d;
  --scar:#8b0000;--flame:#ff2400;--white:#f8f7f3;--offwhite:#d8d7d2;
}
body {
  font-family:'Fira Sans',system-ui,sans-serif;
  font-size:.98rem;line-height:1.58;letter-spacing:0;
  background:linear-gradient(90deg,transparent 0 7%,rgba(123,44,191,.055) 7% 7.08%,transparent 7.08% 92%,rgba(123,44,191,.055) 92% 92.08%,transparent 92.08%),radial-gradient(ellipse 52% 34% at 50% 16%,rgba(49,16,79,.18),transparent 72%),var(--obsidian);
}
body::after {content:'';position:fixed;inset:54px 0 0;pointer-events:none;z-index:1;background:linear-gradient(90deg,transparent 7%,rgba(165,109,226,.09) 7.04%,transparent 7.12%,transparent 91.9%,rgba(165,109,226,.09) 91.96%,transparent 92.05%)}
h1,h2,h3,h4,.hero-name,.sec-title,.tl-title,.sys-col-title,.nexus-title,.nexus-proj-title,.wiki-title,.contact-title,.intj-code,.hstat-n {font-family:'DM Serif Display',Georgia,serif!important;font-weight:400!important;letter-spacing:0!important}
.hero-eyebrow,.hero-ticker,.hstat-l,.sec-num,.sec-tag,.forge-tab,.tl-date,.tl-company,.tag,.sys-col-sub,.sys-skill,.infra-bar,.nexus-sub,.nexus-status,.wiki-cat,.wiki-axiom,.cn-label,.pre-status,.pre-pct,.nav-links,.mob-menu,.lang-toggle,.nav-brand {font-family:'Fira Code',monospace!important}
nav {border-bottom-color:rgba(123,44,191,.36);box-shadow:0 1px 0 rgba(225,181,44,.08),0 12px 36px rgba(0,0,0,.42)}
.nav-brand {color:var(--gold-br)}
.nav-links a {color:rgba(197,231,243,.72)}
.nav-links a::after {background:linear-gradient(90deg,var(--purple-bright),var(--gold))}
#hero {min-height:min(860px,100vh);background:radial-gradient(ellipse 46% 62% at 64% 48%,rgba(7,16,31,.9),transparent 72%),radial-gradient(ellipse 32% 50% at 14% 42%,rgba(49,16,79,.24),transparent 70%),var(--obsidian)!important}
#hero::before {background:linear-gradient(90deg,transparent,var(--scar) 18%,var(--flame) 50%,var(--scar) 82%,transparent);box-shadow:0 0 4px var(--flame),0 0 32px rgba(255,36,0,.34),0 0 72px rgba(139,0,0,.22)}
.hero-inner {max-width:1120px;grid-template-columns:minmax(220px,290px) minmax(0,1fr);gap:clamp(2.5rem,6vw,5.5rem)}
.hero-text {border-left:1px solid rgba(123,44,191,.38);padding-left:clamp(1.5rem,3vw,2.75rem);position:relative}
.hero-text::before {content:'ARCHIVE / 00';position:absolute;left:-1px;top:-2.2rem;color:var(--purple-soft);font:500 .58rem/1 'Fira Code',monospace;letter-spacing:.16em}
.hero-name {font-size:clamp(2.7rem,5.2vw,4.9rem);line-height:.91;margin-bottom:1rem;text-wrap:balance}
.hero-name span {background:linear-gradient(90deg,var(--gold-br),var(--white) 48%,var(--gold) 90%);-webkit-background-clip:text;background-clip:text}
.hero-eyebrow {color:var(--ice)}
.ticker-item {border-color:rgba(123,44,191,.48)!important;color:var(--purple-soft)!important;background:rgba(49,16,79,.18)!important}
.hero-bio {color:rgba(248,247,243,.77);max-width:670px;line-height:1.65}
.photo-ring,.photo-ring2 {border-color:rgba(123,44,191,.32)!important}
.photo-circle {border-color:var(--gold)!important;box-shadow:0 0 0 1px rgba(123,44,191,.34),0 0 28px rgba(123,44,191,.18),0 0 44px rgba(225,181,44,.12)!important}
.photo-status {border-color:rgba(165,109,226,.45)!important;background:rgba(3,3,6,.92)!important}
.btn-gold {color:var(--gold-sh)!important;background:linear-gradient(110deg,rgba(49,16,79,.94),rgba(123,44,191,.62))!important;border-color:rgba(225,181,44,.65)!important;box-shadow:inset 0 0 20px rgba(165,109,226,.08),0 0 18px rgba(123,44,191,.15)!important}
.btn-gold:hover {background:linear-gradient(110deg,rgba(75,22,115,.98),rgba(123,44,191,.78))!important;box-shadow:0 0 24px rgba(123,44,191,.32)!important}
.hero-stats {border-top:1px solid rgba(123,44,191,.28);padding-top:1rem}
.hstat-div {background:rgba(165,109,226,.28)!important}
.section-wrap {max-width:1120px;padding:3.4rem 1.5rem!important}
.sec-head {align-items:flex-end;margin-bottom:2rem!important}
.sec-num {color:var(--purple-soft)!important;border-color:rgba(123,44,191,.38)!important}
.sec-tag {color:var(--olive-soft)!important}
.sec-title {font-size:clamp(2.15rem,4vw,3.55rem)!important;line-height:.98;color:var(--white)!important}
.arc-div {color:rgba(165,109,226,.48)!important}
.architect-grid {grid-template-columns:minmax(0,.86fr) minmax(0,1.5fr);gap:2.2rem!important}
.intj-badge,.architect-quote,.trait-card {background:linear-gradient(145deg,rgba(7,16,31,.86),rgba(49,16,79,.1))!important;border-color:rgba(123,44,191,.3)!important}
.trait-grid {grid-template-columns:repeat(2,minmax(0,1fr))}
.trait-card:nth-child(2),.trait-card:nth-child(3) {border-top-color:rgba(178,195,109,.45)!important}
.forge-tabs {border-bottom-color:rgba(123,44,191,.34)!important}
.forge-tab {color:rgba(197,231,243,.74)!important;background:rgba(7,16,31,.74)!important;border-color:rgba(123,44,191,.25)!important;clip-path:none!important}
.forge-tab:hover {color:var(--purple-soft)!important;border-color:rgba(165,109,226,.52)!important;background:rgba(49,16,79,.24)!important;text-shadow:0 0 8px var(--purple-glow)!important}
.forge-tab.active {color:var(--gold-sh)!important;border-color:rgba(225,181,44,.42)!important;border-bottom-color:var(--purple-bright)!important;background:linear-gradient(180deg,rgba(49,16,79,.54),rgba(7,16,31,.85))!important;text-shadow:none!important;box-shadow:inset 0 -2px 0 var(--purple-bright),0 0 18px rgba(123,44,191,.14)!important}
.svc-note,.sys-intro {border-left-color:var(--olive)!important;background:rgba(115,130,56,.07)!important}
.timeline {padding-left:3rem}
.timeline::before {left:.35rem;background:linear-gradient(180deg,var(--gold),var(--purple-bright) 28%,var(--olive) 62%,var(--purple-bright),var(--gold))!important}
.tl-item {background:linear-gradient(125deg,rgba(7,16,31,.9),rgba(49,16,79,.12))!important;border-color:rgba(123,44,191,.23)!important;border-left:2px solid rgba(123,44,191,.55)!important}
.tl-item:nth-child(3n+2) {margin-right:4.5%}
.tl-item:nth-child(3n) {margin-left:4.5%;border-left-color:rgba(178,195,109,.55)!important}
.tl-item:hover {border-color:rgba(165,109,226,.55)!important;box-shadow:0 0 22px rgba(123,44,191,.12)!important}
.tl-node {background:linear-gradient(135deg,var(--gold),var(--purple-bright))!important;box-shadow:0 0 11px rgba(123,44,191,.56)!important}
.tl-date {color:var(--ice)!important}.tl-title {color:var(--white)!important;font-size:1.36rem!important}.tl-company {color:var(--purple-soft)!important}.tl-bullets {color:rgba(216,215,210,.76)!important}
.tag-r,.tag-p {color:var(--purple-soft)!important;border-color:rgba(123,44,191,.58)!important;background:rgba(49,16,79,.2)!important}
.tag-g {color:var(--olive-soft)!important;border-color:rgba(115,130,56,.7)!important;background:rgba(115,130,56,.09)!important}
.sys-grid {grid-template-columns:1.05fr .95fr 1.05fr;gap:.9rem!important}
.sys-col,.nexus-card,.wiki-card {background:linear-gradient(145deg,rgba(7,16,31,.9),rgba(49,16,79,.1))!important;border-color:rgba(123,44,191,.25)!important}
.sys-col:nth-child(2) {transform:translateY(1.5rem);border-top-color:rgba(225,181,44,.45)!important}
.sys-col-title {color:var(--white)!important;font-size:1.15rem!important;text-shadow:none!important}
.sys-col-sub,.sys-skill-lvl,.nexus-sub,.wiki-cat {color:var(--purple-soft)!important}
.sys-fill::before {background-image:repeating-linear-gradient(90deg,var(--purple-bright) 0 6px,transparent 6px 9px)!important}
.infra-bar {border-color:rgba(123,44,191,.34)!important;background:rgba(49,16,79,.1)!important}
.infra-dot,.status-dot {background:var(--olive-soft)!important;box-shadow:0 0 8px rgba(178,195,109,.52)!important}
.nexus-grid {grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:.9rem!important}
.nexus-card:hover,.wiki-card:hover {border-color:rgba(165,109,226,.56)!important;box-shadow:0 0 22px rgba(123,44,191,.14)!important}
.nexus-status {color:var(--gold-br)!important}
.wiki-grid {grid-template-columns:1.15fr .85fr 1fr;gap:.9rem!important}
.wiki-card {border-top:2px solid rgba(123,44,191,.64)!important;min-height:0!important}
.wiki-card:nth-child(3n+2) {transform:translateY(1.4rem);border-top-color:rgba(178,195,109,.58)!important}
.wiki-card:nth-child(3n) {border-top-color:rgba(225,181,44,.58)!important}
.wiki-title {color:var(--white)!important;font-size:1.35rem!important}.wiki-excerpt {color:rgba(216,215,210,.72)!important}.wiki-axiom {color:var(--olive-soft)!important}
#contact {background:radial-gradient(ellipse 60% 72% at 50% 100%,rgba(49,16,79,.28),transparent 66%),var(--void)!important;border-top:1px solid rgba(123,44,191,.34);padding:3.5rem 1.5rem!important}
.contact-inner {max-width:940px}.contact-title {font-size:clamp(2.25rem,5vw,4rem)!important}.contact-nexus {display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.65rem!important}
.cn-item {border-color:rgba(123,44,191,.28)!important;background:rgba(7,16,31,.72)!important}.cn-label {color:var(--purple-soft)!important}.cn-item:hover {border-color:rgba(165,109,226,.62)!important;box-shadow:0 0 18px rgba(123,44,191,.16)!important}
@media(max-width:900px){body {background:radial-gradient(ellipse 80% 28% at 50% 12%,rgba(49,16,79,.2),transparent 72%),var(--obsidian)}body::after{display:none}#hero{min-height:auto;padding-bottom:3rem!important}.hero-inner{grid-template-columns:1fr;gap:2.4rem}.hero-text{border-left:0;border-top:1px solid rgba(123,44,191,.34);padding:2rem 0 0}.hero-text::before{left:0;top:.65rem}.architect-grid,.nexus-grid{grid-template-columns:1fr}.sys-grid{grid-template-columns:1fr}.sys-col:nth-child(2){transform:none}.wiki-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.wiki-card:nth-child(3n+2){transform:none}.contact-nexus{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:500px){body{font-size:.94rem}#hero{padding-left:1.25rem!important;padding-right:1.25rem!important}.hero-name{font-size:clamp(2.45rem,13vw,3.35rem)!important}.hero-bio{font-size:.95rem;line-height:1.68}.section-wrap{padding:2.7rem 1.25rem!important}.sec-head{gap:.8rem;align-items:flex-start}.sec-line{display:none}.trait-grid,.wiki-grid{grid-template-columns:1fr}.timeline{padding-left:1.6rem}.timeline::before{left:.15rem}.tl-item:nth-child(n){margin-left:0;margin-right:0}.tl-title{font-size:1.2rem!important}.contact-nexus{grid-template-columns:1fr}}
